changeSet.sql:
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_node_name_format CHECK (node_name REGEXP '^[a-zA-Z_][a-zA-Z0-9_]*$');
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_realm_format CHECK (realm REGEXP '^[a-zA-Z_][a-zA-Z0-9-]*[a-zA-Z0-9](\.[a-zA-Z][a-zA-Z0-9-]*[a-zA-Z0-9])*$' AND length(realm) <= 255);
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_fqdn_format CHECK (fqdn REGEXP '^[a-zA-Z_][a-zA-Z0-9-]*[a-zA-Z0-9](\.[a-zA-Z][a-zA-Z0-9-]*[a-zA-Z0-9])*$' AND length(fqdn) <= 255);
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_sctp_listen_port_range CHECK (sctp_listen_port BETWEEN 1024 AND 49151);
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_tcp_listen_port_range CHECK (tcp_listen_port BETWEEN 1024 AND 49151);
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_dtls_sctp_listen_port_range CHECK (dtls_sctp_listen_port BETWEEN 1024 AND 49151);
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_tls_tcp_listen_port_range CHECK (tls_tcp_listen_port BETWEEN 1024 AND 49151);
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_radius_port_range CHECK (radius_client_udp_port_range_start BETWEEN 1024 AND 49151 AND radius_client_udp_port_range_end BETWEEN 1024 AND 49151 AND radius_client_udp_port_range_start <= radius_client_udp_port_range_end);
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_verification_mode CHECK (verification_mode IN ('Verify None', 'Verify Peer', 'Fail if No Peer Certificate', 'Verify Client Once'));
ALTER TABLE tblpeerconfiguration ADD CONSTRAINT chk_radius_client_ports_when_enabled CHECK ((enable_radius_udp_client_ports = false AND radius_client_udp_port_range_start IS NULL AND radius_client_udp_port_range_end IS NULL) OR (enable_radius_udp_client_ports = true AND radius_client_udp_port_range_start IS NOT NULL AND radius_client_udp_port_range_end IS NOT NULL));


ALTER TABLE tblpeerconfiguration 
ADD CONSTRAINT chk_remote_port_range 
CHECK (remote_port BETWEEN 1024 AND 49151);

ALTER TABLE tblpeerconfiguration 
ADD CONSTRAINT chk_status 
CHECK (status IN ('Active', 'Inactive', 'Deleted'));

ALTER TABLE tblpeerconfiguration
ADD CONSTRAINT chk_watchdog_interval
CHECK (watchdog_interval > 0);


ALTER TABLE tblpeerconfiguration 
ADD CONSTRAINT chk_description_length 
CHECK (description IS NULL OR length(description) <= 500);
